"""Algorithm 1 -- Frobenius Congruence Certificate in Z[zeta_n].

Given n, a prime p, and an element x of the order Z[zeta_n] (represented as an
integer polynomial modulo the n-th cyclotomic polynomial), this algorithm
produces an explicit witness w with

        sigma_p(x) - x^p = p * w,          sigma_p : zeta -> zeta^p,

thereby certifying the Frobenius congruence.  Cost: O(log p) ring
multiplications, i.e. O~(phi(n)^2 log p) bit operations.
"""

from __future__ import annotations

import math
from typing import List, Optional, Tuple

Poly = List[int]


def _trim(a: Poly) -> Poly:
    b = list(a)
    while b and b[-1] == 0:
        b.pop()
    return b


def poly_add(a: Poly, b: Poly) -> Poly:
    n = max(len(a), len(b))
    return _trim([(a[i] if i < len(a) else 0) + (b[i] if i < len(b) else 0) for i in range(n)])


def poly_sub(a: Poly, b: Poly) -> Poly:
    n = max(len(a), len(b))
    return _trim([(a[i] if i < len(a) else 0) - (b[i] if i < len(b) else 0) for i in range(n)])


def poly_mul(a: Poly, b: Poly) -> Poly:
    if not a or not b:
        return []
    out = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        if ai:
            for j, bj in enumerate(b):
                out[i + j] += ai * bj
    return _trim(out)


def poly_divmod_monic(a: Poly, m: Poly) -> Tuple[Poly, Poly]:
    """Divide by a monic polynomial m over Z."""
    q: Poly = [0] * max(0, len(a) - len(m) + 1)
    r = list(a)
    while _trim(r) and len(_trim(r)) >= len(m):
        r = _trim(r)
        s = len(r) - len(m)
        c = r[-1]
        q[s] = c
        for i, mi in enumerate(m):
            r[s + i] -= c * mi
    return _trim(q), _trim(r)


def cyclotomic(n: int) -> Poly:
    """Phi_n(X) via  X^n - 1 = prod_{d | n} Phi_d(X)."""
    if n == 1:
        return [-1, 1]
    num: Poly = [0] * n + [1]
    num[0] = -1
    for d in range(1, n):
        if n % d == 0:
            num, rem = poly_divmod_monic(num, cyclotomic(d))
            assert not rem
    return num


def ring_mul(a: Poly, b: Poly, phi: Poly) -> Poly:
    return poly_divmod_monic(poly_mul(a, b), phi)[1]


def ring_pow(a: Poly, e: int, phi: Poly) -> Poly:
    result: Poly = [1]
    base = poly_divmod_monic(a, phi)[1]
    while e:
        if e & 1:
            result = ring_mul(result, base, phi)
        base = ring_mul(base, base, phi)
        e >>= 1
    return result


def power_map(a: Poly, m: int, n: int, phi: Poly) -> Poly:
    """Apply the power map sigma_m : zeta -> zeta^m to a(zeta)."""
    out: Poly = []
    for i, c in enumerate(a):
        if c:
            out = poly_add(out, [c * t for t in ring_pow([0, 1], (i * m) % n, phi)])
    return poly_divmod_monic(out, phi)[1]


def frobenius_certificate(n: int, p: int, x: Poly) -> Optional[Poly]:
    """Return w with sigma_p(x) - x^p = p*w, or None if the congruence fails."""
    phi = cyclotomic(n)
    defect = poly_sub(power_map(x, p, n, phi), ring_pow(x, p, phi))
    if any(c % p for c in defect):
        return None
    return _trim([c // p for c in defect])


if __name__ == "__main__":
    for (n, p, x) in [(5, 3, [1, -2, 0, 3]), (7, 2, [2, 1, -1, 0, 4]), (12, 5, [-1, 3, 2])]:
        w = frobenius_certificate(n, p, x)
        assert w is not None, "Frobenius congruence must hold"
        print(f"n={n:2d} p={p}: witness w = {w}   (sigma_p(x) - x^p = {p}*w)")

"""Algorithm 2 -- Frobenius Identification and Rigidity Certificate.

Fix n, a prime p not dividing n, and a prime Q of the order Z[zeta_n] lying over
p.  Concretely, Q = (p, g(zeta)) where g is a monic irreducible factor of the
n-th cyclotomic polynomial modulo p, so that the residue ring is F_p[X]/(g).

The algorithm enumerates all phi(n) power maps sigma_m (m coprime to n) and
tests the defining Frobenius congruence sigma_m(x) = x^p (mod Q) on a spanning
set.  Theory predicts a unique survivor, namely m congruent to p modulo n; the
algorithm returns the full list, so an empty or multi-element answer would
falsify the rigidity theorem.

Cost: factoring Phi_n mod p (O(phi(n)^2 log p) with a standard equal-degree
routine; here trial division for readability), then phi(n) congruence tests each
costing O(log p) multiplications in F_p[X]/(g).
"""

from __future__ import annotations

import math
from typing import Iterator, List, Sequence, Tuple

Poly = List[int]


def _trim(a: Poly) -> Poly:
    b = list(a)
    while b and b[-1] == 0:
        b.pop()
    return b


def poly_mul_mod(a: Poly, b: Poly, p: int) -> Poly:
    if not a or not b:
        return []
    out = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        if ai:
            for j, bj in enumerate(b):
                out[i + j] = (out[i + j] + ai * bj) % p
    return _trim(out)


def poly_divmod_modp(a: Poly, m: Poly, p: int) -> Tuple[Poly, Poly]:
    m = _trim([c % p for c in m])
    inv = pow(m[-1], -1, p)
    q: Poly = [0] * max(0, len(a) - len(m) + 1)
    r = [c % p for c in a]
    while _trim(r) and len(_trim(r)) >= len(m):
        r = _trim(r)
        s = len(r) - len(m)
        c = (r[-1] * inv) % p
        q[s] = c
        for i, mi in enumerate(m):
            r[s + i] = (r[s + i] - c * mi) % p
    return _trim(q), _trim(r)


def cyclotomic(n: int) -> Poly:
    if n == 1:
        return [-1, 1]
    num: Poly = [0] * n + [1]
    num[0] = -1
    for d in range(1, n):
        if n % d == 0:
            num, rem = _divmod_int(num, cyclotomic(d))
            assert not rem
    return num


def _divmod_int(a: Poly, m: Poly) -> Tuple[Poly, Poly]:
    q: Poly = [0] * max(0, len(a) - len(m) + 1)
    r = list(a)
    while _trim(r) and len(_trim(r)) >= len(m):
        r = _trim(r)
        s = len(r) - len(m)
        c = r[-1]
        q[s] = c
        for i, mi in enumerate(m):
            r[s + i] -= c * mi
    return _trim(q), _trim(r)


def monic_polys(deg: int, p: int) -> Iterator[Poly]:
    def rec(prefix: List[int], k: int) -> Iterator[Poly]:
        if k == 0:
            yield prefix + [1]
            return
        for c in range(p):
            yield from rec(prefix + [c], k - 1)
    return rec([], deg)


def prime_above(n: int, p: int) -> Poly:
    """A monic irreducible factor g of Phi_n mod p; Q = (p, g(zeta))."""
    f = [c % p for c in cyclotomic(n)]
    for deg in range(1, len(f)):
        for g in monic_polys(deg, p):
            if not poly_divmod_modp(f, g, p)[1]:
                return g
    raise RuntimeError("Phi_n has no factor: impossible")


def residue_pow(a: Poly, e: int, g: Poly, p: int) -> Poly:
    result: Poly = [1]
    base = poly_divmod_modp(a, g, p)[1]
    while e:
        if e & 1:
            result = poly_divmod_modp(poly_mul_mod(result, base, p), g, p)[1]
        base = poly_divmod_modp(poly_mul_mod(base, base, p), g, p)[1]
        e >>= 1
    return result


def residue_power_map(a: Poly, m: int, n: int, g: Poly, p: int) -> Poly:
    out: Poly = []
    for i, c in enumerate(a):
        if c % p:
            t = residue_pow([0, 1], (i * m) % n, g, p)
            out = _trim([((out[k] if k < len(out) else 0) + c * (t[k] if k < len(t) else 0)) % p
                         for k in range(max(len(out), len(t)))])
    return poly_divmod_modp(out, g, p)[1]


def frobenius_candidates(n: int, p: int, num_tests: int = 6) -> Tuple[Poly, List[int]]:
    """Return (g, winners): the prime Q = (p, g) and all m with sigma_m Frobenius."""
    if n % p == 0:
        raise ValueError("p must not divide n")
    g = prime_above(n, p)
    tests: List[Poly] = [[0, 1], [1, 1], [1, 0, 1], [2, 3], [1, 1, 1], [3, 0, 0, 2]][:num_tests]
    winners: List[int] = []
    for m in range(1, n + 1):
        if math.gcd(m, n) != 1:
            continue
        if all(residue_power_map(x, m, n, g, p) == residue_pow(x, p, g, p) for x in tests):
            winners.append(m % n)
    return g, winners


if __name__ == "__main__":
    for (n, p) in [(5, 3), (7, 3), (8, 5), (11, 2), (12, 7), (15, 7)]:
        g, winners = frobenius_candidates(n, p)
        print(f"n={n:2d} p={p:2d}: Q=(p, g) with g={g};  Frobenius maps: "
              f"{['zeta -> zeta^%d' % m for m in winners]}  (predicted m = {p % n})")
        assert winners == [p % n], "rigidity violated"

